18	//   ~/.gemini/antigravity-cli/brain/<conversation-id>/.system_generated/logs/transcript_full.jsonl
19	// The on-disk schema is a sequence of "step" objects:
20	//   {
21	//     "step_index":  int,
22	//     "source":      "USER_EXPLICIT" | "SYSTEM" | "MODEL" | ...,
23	//     "type":        "USER_INPUT" | "CONVERSATION_HISTORY" | "PLANNER_RESPONSE" | ...,
24	//     "status":      "DONE" | ...,
25	//     "created_at":  RFC3339 timestamp,
26	//     "content":     string (optional — user request / model text),
27	//     "tool_calls":  [ { "name": string, "args": object } ] (optional)
28	//   }
29	// v1 ships JSONL chunk/reassemble passthrough plus prompt extraction. Token
