104	func cleanAntigravityPrompt(content string) string {
105		content = strings.TrimSpace(content)
106		if content == "" {
107			return ""
108		}
109	
110		if start := strings.Index(content, "<USER_REQUEST>"); start >= 0 {
111			content = content[start+len("<USER_REQUEST>"):]
112			if end := strings.Index(content, "</USER_REQUEST>"); end >= 0 {
113				content = content[:end]
114			}
115		}
116		if metadata := strings.Index(content, "<ADDITIONAL_METADATA>"); metadata >= 0 {
117			content = content[:metadata]
118		}
119		content = strings.TrimSpace(content)
120	
121		const requestMarker = "Request:\n"
122		if idx := strings.Index(content, requestMarker); idx >= 0 {
123			content = content[idx+len(requestMarker):]
124		}
125	
126		return textutil.StripIDEContextTags(content)
127	}
