129	// PrepareTranscript implements the optional TranscriptPreparer interface. The
130	// framework calls this in handleLifecycleTurnEnd BEFORE its fileExists check
131	// — so we use it to handle agy's asynchronous transcript write.
132	//
133	// Background: agy writes its transcript file at
134	//
135	//	~/.gemini/antigravity-cli/brain/<conv-id>/.system_generated/logs/transcript_full.jsonl
136	//
137	// AFTER the Stop hook fires (sometimes seconds later, depending on session
138	// shutdown timing). Our TurnEnd event maps to Stop, so we routinely race the
139	// transcript write. Without PrepareTranscript, the framework's fileExists
140	// check fails with "transcript file not found" and our hook returns exit 1,
141	// terminating agy's agent turn.
142	//
143	// We briefly wait for the real transcript first. If it is still missing,
144	// we materialise an empty placeholder. files_touched is already captured via
145	// the PreToolUse hook (independent of transcript content), so condensation can
146	// still produce a meaningful checkpoint from an empty transcript.
147	func (a *AntigravityAgent) PrepareTranscript(ctx context.Context, transcriptRef string) error {
148		if transcriptRef == "" {
149			return nil
150		}
151	
152		deadline := time.Now().Add(1 * time.Second)
153		if ctxDeadline, ok := ctx.Deadline(); ok && ctxDeadline.Before(deadline) {
154			deadline = ctxDeadline
155		}
156	
157		for {
158			info, err := os.Stat(transcriptRef)
159			if err == nil {
160				if info.Size() > 0 {
161					return nil
162				}
163			} else if !os.IsNotExist(err) {
164				return fmt.Errorf("antigravity: stat transcript: %w", err)
165			}
166	
167			if !time.Now().Before(deadline) {
168				break
169			}
170	
171			wait := 50 * time.Millisecond
172			if remaining := time.Until(deadline); remaining < wait {
173				wait = remaining
174			}
175			timer := time.NewTimer(wait)
176			select {
177			case <-ctx.Done():
178				if !timer.Stop() {
179					<-timer.C
180				}
181				return fmt.Errorf("antigravity: context ended while waiting for transcript: %w", ctx.Err())
182			case <-timer.C:
183			}
184		}
185	
186		if err := os.MkdirAll(filepath.Dir(transcriptRef), 0o750); err != nil {
187			return fmt.Errorf("antigravity: prepare transcript dir: %w", err)
188		}
189		if _, err := os.Stat(transcriptRef); err == nil {
190			return nil
191		} else if !os.IsNotExist(err) {
192			return fmt.Errorf("antigravity: stat transcript before placeholder: %w", err)
193		}
194		file, err := os.OpenFile(transcriptRef, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) //nolint:gosec // path supplied by agent hook stdin
195		if err != nil {
196			if os.IsExist(err) {
197				return nil
198			}
199			return fmt.Errorf("antigravity: create empty transcript placeholder: %w", err)
200		}
201		if err := file.Close(); err != nil {
202			return fmt.Errorf("antigravity: close empty transcript placeholder: %w", err)
203		}
204		return nil
205	}
