	// The regression itself: prompts extracted at the corrected offset must not
	// include the previous turn's prompt (and the stale offset must — that is
	// the bug being prevented).
	stale := resolvePromptsFromLateFlushedTranscript(context.Background(), ag, path, 2)
	require.Equal(t, []string{"second prompt"}, stale,
		"sanity: at the stale offset the previous condensation boundary leaks the next turn's region")
	corrected := resolvePromptsFromLateFlushedTranscript(context.Background(), ag, path, state.CheckpointTranscriptStart)
	require.Empty(t, corrected, "at the corrected offset no already-condensed prompt leaks into the next checkpoint")
}

